const CACHE='future-compass-20261004-v13';
const ASSETS=["study.html","study.js","study.css","focus-ui.js","focus-ui.css","shiro-help.js","shiro-help.css","know-me.html","know-me.css","know-me.js","know-me-data.js","know-me-entry.js","career-depth.js", "career-depth.css", "career-lab.js", "career-lab.css", "phone-friend.jpg", "cozy-study.jpg", "future-friend.jpg", "shiro-letter.jpg", "./", "index.html", "ui.css", "app.css", "explore.js", "shell.js", "news.js", "news.json", "manifest.webmanifest", "app-icon.svg", "app-icon-192.png", "app-icon-512.png", "icons/stethoscope.svg", "icons/newspaper.svg", "icons/heart.svg", "icons/arrow-up-right.svg", "icons/building-2.svg", "icons/palette.svg", "icons/leaf.svg", "icons/shield-check.svg", "icons/chart-no-axes-combined.svg", "icons/house.svg", "icons/lightbulb.svg", "icons/graduation-cap.svg", "icons/flask-conical.svg", "icons/sparkles.svg", "icons/circle-check.svg", "icons/bot.svg", "icons/download.svg", "icons/wheat.svg", "icons/menu.svg", "icons/book-open.svg", "icons/compass.svg", "icons/cpu.svg"];
self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(CACHE);for(const asset of ASSETS){try{const r=await fetch(asset,{cache:'reload'});if(r.ok&&!r.redirected)await cache.put(asset,r)}catch{}}})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith('future-compass-')&&key!==CACHE)await caches.delete(key);await self.clients.claim()})()));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin)return;const relative=url.pathname.slice(new URL(self.registration.scope).pathname.length);if(event.request.mode==='navigate'&&!['','index.html'].includes(relative))return;if(event.request.mode!=='navigate'&&!ASSETS.includes(relative))return;event.respondWith((async()=>{const cache=await caches.open(CACHE);try{const response=await fetch(event.request);if(response.ok&&!response.redirected)await cache.put(event.request,response.clone());return response}catch{return await cache.match(event.request)||await cache.match(event.request.mode==='navigate'?'index.html':relative)||new Response('Offline',{status:503})}})())});

